-- OpenWord initial schema.
--
-- Conventions: ids are uuids generated by Postgres; timestamps are
-- timestamptz; "days" are the client's local calendar date as a YYYY-MM-DD
-- text, never converted by the server.

CREATE TABLE users (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Stored lowercased; the CHECK mirrors the validation in Go.
    username                text NOT NULL,
    display_name            text NOT NULL,
    bio                     text NOT NULL DEFAULT '',
    -- Stored lowercased; NULL when the user gave none.
    email                   text NULL,
    password_hash           text NOT NULL,
    avatar                  bytea NULL,
    avatar_type             text NULL,
    avatar_version          integer NOT NULL DEFAULT 0,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    reminder_time           text NULL,            -- 'HH:MM' local time
    reminder_tz             text NULL,            -- IANA zone name
    reminder_days           integer NOT NULL DEFAULT 127, -- bitmask Mon=1 … Sun=64
    reminder_only_if_undone boolean NOT NULL DEFAULT true,
    friend_reminders        boolean NOT NULL DEFAULT true,
    last_seen_at            timestamptz NULL,
    CONSTRAINT users_username_format CHECK (username ~ '^[a-z0-9_]{3,24}$'),
    CONSTRAINT users_display_name_len CHECK (char_length(display_name) BETWEEN 1 AND 40),
    CONSTRAINT users_bio_len CHECK (char_length(bio) <= 160),
    CONSTRAINT users_email_lower CHECK (email IS NULL OR email = lower(email)),
    CONSTRAINT users_reminder_days_range CHECK (reminder_days BETWEEN 0 AND 127)
);
CREATE UNIQUE INDEX users_username_key ON users (username);
CREATE UNIQUE INDEX users_email_key ON users (email) WHERE email IS NOT NULL;
-- Search by display name is a case-insensitive substring match.
CREATE INDEX users_display_name_lower_idx ON users (lower(display_name));

CREATE TABLE sessions (
    token_hash  bytea PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL,
    user_agent  text NOT NULL DEFAULT ''
);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

CREATE TABLE friendships (
    user_a      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    user_b      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_a, user_b),
    CONSTRAINT friendships_ordered CHECK (user_a < user_b)
);
CREATE INDEX friendships_user_b_idx ON friendships (user_b);

CREATE TABLE friend_requests (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    from_user   uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    to_user     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    message     text NOT NULL DEFAULT '',
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (from_user, to_user),
    CONSTRAINT friend_requests_not_self CHECK (from_user <> to_user)
);
CREATE INDEX friend_requests_to_user_idx ON friend_requests (to_user);

CREATE TABLE activity_days (
    user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    day         text NOT NULL,
    kind        text NOT NULL CHECK (kind IN ('learn','read','plan','quiz','listen')),
    count       integer NOT NULL DEFAULT 1,
    first_at    timestamptz NOT NULL DEFAULT now(),
    last_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, day, kind),
    CONSTRAINT activity_days_day_format CHECK (day ~ '^\d{4}-\d{2}-\d{2}$')
);
CREATE INDEX activity_days_user_day_idx ON activity_days (user_id, day);

CREATE TABLE streak_snapshots (
    user_id     uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    current     integer NOT NULL DEFAULT 0,
    best        integer NOT NULL DEFAULT 0,
    freezes     integer NOT NULL DEFAULT 0,
    last_day    text NOT NULL DEFAULT '',
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE achievements (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    key         text NOT NULL,
    kind        text NOT NULL CHECK (kind IN ('badge','level','streak','plan','quiz','memory','friend')),
    title       text NOT NULL,
    detail      text NOT NULL DEFAULT '',
    earned_at   timestamptz NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (user_id, key)
);
CREATE INDEX achievements_user_earned_idx ON achievements (user_id, earned_at DESC);

CREATE TABLE cheers (
    achievement_id  uuid NOT NULL REFERENCES achievements(id) ON DELETE CASCADE,
    user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (achievement_id, user_id)
);

CREATE TABLE push_subscriptions (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    endpoint      text NOT NULL UNIQUE,
    p256dh        text NOT NULL,
    auth          text NOT NULL,
    user_agent    text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_used_at  timestamptz NULL,
    failures      integer NOT NULL DEFAULT 0
);
CREATE INDEX push_subscriptions_user_id_idx ON push_subscriptions (user_id);

CREATE TABLE backups (
    user_id     uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    body        jsonb NOT NULL,
    updated_at  timestamptz NOT NULL DEFAULT now(),
    size_bytes  integer NOT NULL
);

-- One row per reminder actually sent, so a reminder goes out at most once
-- per local day per kind even if the scheduler ticks twice.
CREATE TABLE reminder_log (
    user_id  uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    day      text NOT NULL,
    kind     text NOT NULL CHECK (kind IN ('daily','friend')),
    sent_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, day, kind)
);

-- Server-generated secrets (VAPID key pair) so they survive restarts without
-- environment configuration.
CREATE TABLE server_keys (
    name   text PRIMARY KEY,
    value  text NOT NULL
);
